'use strict';

/**
* 64-bit unsigned integer array.
*
* @module @stdlib/array/uint64
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var arr = new Uint64Array();
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 0
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var arr = new Uint64Array( 2 );
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 2
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var arr = new Uint64Array( [ 1 ] );
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 1
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var buf = new ArrayBuffer( 32 );
* var arr = new Uint64Array( buf );
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 4
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var buf = new ArrayBuffer( 32 );
* var arr = new Uint64Array( buf, 16 );
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 2
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var buf = new ArrayBuffer( 64 );
* var arr = new Uint64Array( buf, 16, 2 );
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 2
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
